\": \"goToSlideType\",\n                    \"type\": \"select\",\n                    \"label\": \"Go to\",\n                    \"importance\": \"medium\",\n                    \"optional\": false,\n                    \"options\": [\n                      {\n                        \"value\": \"specified\",\n                        \"label\": \"Specific slide number\"\n                      },\n                      {\n                        \"value\": \"next\",\n                        \"label\": \"Next slide\"\n                      },\n                      {\n                        \"value\": \"previous\",\n                        \"label\": \"Previous slide\"\n                      }\n                    ],\n                    \"default\": \"specified\"\n                  },\n                  {\n                    \"name\": \"goToSlide\",\n                    \"type\": \"number\",\n                    \"label\": \"Specific slide number\",\n                    \"description\": \"Only applicable when \'Specific slide number\' is selected\",\n                    \"importance\": \"low\",\n                    \"min\": 1,\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"invisible\",\n                    \"type\": \"boolean\",\n                    \"label\": \"Invisible\",\n                    \"importance\": \"low\",\n                    \"description\": \"Default cursor, no title and no tab index. Warning: Users with disabilities or keyboard only users will have trouble using this element.\",\n                    \"default\": false\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"keywords\",\n              \"importance\": \"low\",\n              \"type\": \"list\",\n              \"optional\": true,\n              \"field\": {\n                \"name\": \"keyword\",\n                \"importance\": \"low\",\n                \"type\": \"group\",\n                \"optional\": true,\n                \"fields\": [\n                  {\n                    \"name\": \"main\",\n                    \"importance\": \"low\",\n                    \"type\": \"text\",\n                    \"optional\": true\n                  },\n                  {\n                    \"name\": \"subs\",\n                    \"importance\": \"low\",\n                    \"type\": \"list\",\n                    \"optional\": true,\n                    \"field\": {\n                      \"name\": \"keyword\",\n                      \"importance\": \"low\",\n                      \"type\": \"text\"\n                    }\n                  }\n                ]\n              }\n            },\n            {\n              \"name\": \"slideBackgroundSelector\",\n              \"importance\": \"medium\",\n              \"type\": \"group\",\n              \"widget\": \"radioSelector\",\n              \"fields\": [\n                {\n                  \"name\": \"imageSlideBackground\",\n                  \"type\": \"image\",\n                  \"label\": \"Image\",\n                  \"importance\": \"medium\",\n                  \"optional\": true,\n                  \"description\": \"Image background should have a 2:1 width to height ratio to avoid stretching. High resolution images will display better on larger screens.\"\n                },\n                {\n                  \"name\": \"fillSlideBackground\",\n                  \"importance\": \"medium\",\n                  \"type\": \"text\",\n                  \"widget\": \"colorSelector\",\n                  \"label\": \"Pick a color\",\n                  \"spectrum\": {\n                    \"flat\": true,\n                    \"showInput\": true,\n                    \"allowEmpty\": true,\n                    \"showButtons\": false\n                  },\n                  \"default\": null,\n                  \"optional\": true\n                }\n       