(54,'H5P.SimpleMultiChoice','Simple Multi Choice',1,1,22,0,0,'','dist/dist.js','dist/styles.css','','[\n  {\n    \"name\": \"question\",\n    \"label\": \"Question\",\n    \"importance\": \"high\",\n    \"type\": \"text\"\n  },\n  {\n    \"name\": \"inputType\",\n    \"label\": \"Multiple choice type\",\n    \"importance\": \"high\",\n    \"type\": \"select\",\n    \"options\": [\n      {\n        \"label\": \"Multiple answers\",\n        \"value\": \"checkbox\"\n      },\n      {\n        \"label\": \"Single answer\",\n        \"value\": \"radio\"\n      }\n    ],\n    \"default\": \"checkbox\"\n  },\n  {\n    \"name\": \"alternatives\",\n    \"label\": \"Answer alternatives\",\n    \"type\": \"list\",\n    \"importance\": \"high\",\n    \"entity\": \"Alternative\",\n    \"min\": 2,\n    \"field\": {\n      \"type\": \"group\",\n      \"name\": \"alternative\",\n      \"label\": \"Alternative\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"label\": \"Text\",\n          \"importance\": \"high\",\n          \"type\": \"text\"\n        },\n        {\n          \"name\": \"feedback\",\n          \"type\": \"group\",\n          \"label\": \"Feedback\",\n          \"importance\": \"low\",\n          \"optional\": true,\n          \"fields\": [\n            {\n              \"name\": \"chosenFeedback\",\n              \"type\": \"text\",\n              \"widget\": \"html\",\n              \"label\": \"Message displayed if answer is selected\",\n              \"importance\": \"low\",\n              \"description\": \"Message will appear below the answer on \\\"continue\\\" if this answer is selected.\",\n              \"optional\": true,\n              \"tags\": [\n                \"strong\",\n                \"em\",\n                \"sub\",\n                \"sup\",\n                \"a\",\n                \"code\"\n              ]\n            },\n            {\n              \"name\": \"notChosenFeedback\",\n              \"type\": \"text