(55,'H5P.SingleChoiceSet','Single Choice Set',1,11,44,1,0,'iframe','scripts/stop-watch.js, scripts/sound-effects.js, scripts/xapi-event-builder.js, scripts/result-slide.js, scripts/solution-view.js, scripts/single-choice-alternative.js, scripts/single-choice.js, scripts/single-choice-set.js','styles/single-choice-set.css','','[\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"List of questions\",\n    \"importance\": \"high\",\n    \"entity\": \"question\",\n    \"min\": 1,\n    \"defaultNum\": 2,\n    \"widgets\": [\n      {\n        \"name\": \"ListEditor\",\n        \"label\": \"Default\"\n      },\n      {\n        \"name\": \"SingleChoiceSetTextualEditor\",\n        \"label\": \"Textual\"\n      }\n    ],\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"isSubContent\": true,\n      \"label\": \"Question & alternatives\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"question\",\n          \"type\": \"text\",\n          \"widget\": \"html\",\n          \"tags\": [\n            \"p\",\n            \"br\",\n            \"strong\",\n            \"em\",\n            \"code\"\n          ],\n          \"label\": \"Question\",\n          \"importance\": \"high\"\n        },\n        {\n          \"name\": \"answers\",\n          \"type\": \"list\",\n          \"label\": \"Alternatives - first alternative is the correct one.\",\n          \"importance\": \"medium\",\n          \"entity\": \"answer\",\n          \"min\": 2,\n          \"max\": 4,\n          \"defaultNum\": 2,\n          \"field\": {\n            \"name\": \"answer\",\n            \"type\": \"text\",\n            \"widget\": \"html\",\n            \"tags\": [\n              \"p\",\n              \"br\",\n              \"strong\",\n              \"em\",\n              \"code\"\n            ],\n            \"label\": \"Alternative\",\n            \"importance\": \"medium\"\n          }\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"autoContinue\",\n        \"type\": \"boolean\",\n        \"label\": \"Auto continue\",\n        \"description\": \"Automatically go to next question when alternative is selected. This needs to be turned off to make the content fully accessible when using a screen reader.\",\n        \"default\": true\n      },\n      {\n        \"name\": \"timeoutCorrect\",\n        \"type\": \"number\",\n        \"label\": \"Timeout on correct answers\",\n        \"importance\": \"low\",\n        \"description\": \"Value in milliseconds\",\n        \"default\": 2000,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"autoContinue\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"timeoutWrong\",\n        \"type\": \"number\",\n        \"label\": \"Timeout on wrong answers\",\n        \"importance\": \"low\",\n        \"description\": \"Value in milliseconds\",\n        \"default\": 3000,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"autoContinue\",\n              \"equals\": true\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"soundEffectsEnabled\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable sound effects\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableRetry\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable retry button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"enableSolutionsButton\",\n        \"type\": \"boolean\",\n        \"label\": \"Enable show solution button\",\n        \"importance\": \"low\",\n        \"default\": true\n      },\n      {\n        \"name\": \"passPercentage\",\n        \"type\": \"number\",\n        \"label\": \"Pass percentage\",\n        \"description\": \"Percentage of Total score required for