{\n            \"value\": \"-5:00\",\n            \"label\": \"UTC-5:00\"\n          },\n          {\n            \"value\": \"-4:00\",\n            \"label\": \"UTC-4:00\"\n          },\n          {\n            \"value\": \"-3:30\",\n            \"label\": \"UTC-3:30\"\n          },\n          {\n            \"value\": \"-3:00\",\n            \"label\": \"UTC-3:00\"\n          },\n          {\n            \"value\": \"-2:00\",\n            \"label\": \"UTC-2:00\"\n          },\n          {\n            \"value\": \"-1:00\",\n            \"label\": \"UTC-1:00\"\n          },\n          {\n            \"value\": \"0:00\",\n            \"label\": \"UTC\"\n          },\n          {\n            \"value\": \"1:00\",\n            \"label\": \"UTC+1:00\"\n          },\n          {\n            \"value\": \"2:00\",\n            \"label\": \"UTC+2:00\"\n          },\n          {\n            \"value\": \"3:00\",\n            \"label\": \"UTC+3:00\"\n          },\n          {\n            \"value\": \"3:30\",\n            \"label\": \"UTC+3:30\"\n          },\n          {\n            \"value\": \"4:00\",\n            \"label\": \"UTC+4:00\"\n          },\n          {\n            \"value\": \"4:00\",\n            \"label\": \"UTC+4:30\"\n          },\n          {\n            \"value\": \"5:00\",\n            \"label\": \"UTC+5:00\"\n          },\n          {\n            \"value\": \"5:30\",\n            \"label\": \"UTC+5:30\"\n          },\n          {\n            \"value\": \"5:45\",\n            \"label\": \"UTC+5:45\"\n          },\n          {\n            \"value\": \"6:00\",\n            \"label\": \"UTC+6:00\"\n          },\n          {\n            \"value\": \"6:30\",\n            \"label\": \"UTC+6:30\"\n          },\n          {\n            \"value\": \"7:00\",\n            \"label\": \"UTC+7:00\"\n          },\n          {\n            \"value\": \"8:00\",\n            \"label\": \"UTC+8:00\"\n          },\n          {\n            \"value\": \"9:00\",\n            \"label\": \"UTC+9:00\"\n          },\n          {\n            \"value\": \"9:30\",\n            \"label\": \"UTC+9:30\"\n          },\n          {\n            \"value\": \"10:00\",\n            \"label\": \"UTC+10:00\"\n          },\n          {\n            \"value\": \"10:30\",\n            \"label\": \"UTC+10:30\"\n          },\n          {\n            \"value\": \"11:00\",\n            \"label\": \"UTC+11:00\"\n          },\n          {\n            \"value\": \"12:00\",\n            \"label\": \"UTC+12:00\"\n          },\n          {\n            \"value\": \"12:45\",\n            \"label\": \"UTC+12:45\"\n          },\n          {\n            \"value\": \"13:00\",\n            \"label\": \"UTC+13:00\"\n          },\n          {\n            \"value\": \"14:00\",\n            \"label\": \"UTC+14:00\"\n          }\n        ],\n        \"default\": \"0:00\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"allDay\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"daylightSavings\",\n        \"type\": \"boolean\",\n        \"label\": \"Daylight savings\",\n        \"description\": \"Check if location that the event is taking place in uses daylight savings time\",\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"allDay\",\n              \"equals\": false\n            }\n          ]\n        }\n      },\n      {\n        \"name\": \"location\",\n        \"type\": \"text\",\n        \"label\": \"Location\",\n        \"description\": \"Name the location\",\n        \"placeholder\": \"Madison, USA\",\n        \"optional\": true,\n        \"maxLength\": 200\n      },\n      {\n        \"name\": \"description\",\n        \"type\": \"text\",\n        \"label\": \"Description\",\n        \"description\": \"Add a description for the event\",\n