          \"H5P.DragText 1.10\",\n          \"H5P.Essay 1.5\",\n          \"H5P.FindTheWords 1.4\",\n          \"H5P.Flashcards 1.6\",\n          \"H5P.GuessTheAnswer 1.5\",\n          \"H5P.Table 1.1\",\n          \"H5P.AdvancedText 1.1\",\n          \"H5P.IFrameEmbed 1.0\",\n          \"H5P.Image 1.1\",\n          \"H5P.MultiMediaChoice 0.3\",\n          \"H5P.ImageHotspots 1.10\",\n          \"H5P.ImageHotspotQuestion 1.8\",\n          \"H5P.ImageJuxtaposition 1.5\",\n          \"H5P.ImagePair 1.4\",\n          \"H5P.ImageSequencing 1.1\",\n          \"H5P.ImageSlider 1.1\",\n          \"H5P.InteractiveBook 1.7\",\n          \"H5P.InteractiveVideo 1.26\",\n          \"H5P.Link 1.3\",\n          \"H5P.MarkTheWords 1.11\",\n          \"H5P.MemoryGame 1.3\",\n          \"H5P.MultiChoice 1.16\",\n          \"H5P.Questionnaire 1.3\",\n          \"H5P.QuestionSet 1.20\",\n          \"H5P.SingleChoiceSet 1.11\",\n          \"H5P.SortParagraphs 0.11\",\n          \"H5P.Summary 1.10\",\n          \"H5P.Timeline 1.1\",\n          \"H5P.TrueFalse 1.8\",\n          \"H5P.Video 1.6\",\n          \"H5P.ThreeImage 0.5\"\n        ]\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"h5p\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"location\",\n    \"type\": \"group\",\n    \"label\": \"Location\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"latitude\",\n        \"type\": \"text\",\n        \"label\": \"Latitude\",\n        \"description\": \"Latitude (please use the format 53.864462)\",\n        \"placeholder\": \"69.646007\",\n        \"regexp\": {\n          \"pattern\": \"^((-?0*([0-9]|[1-7][0-9]|8[0-9])(\\\\.[0-9]{1,6})?)|(-?90))$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"longitude\",\n        \"type\": \"text\",\n        \"label\": \"Longitude\",\n        \"description\": \"Longitude (please use the format 10.663792)\",\n        \"placeholder\": \"18.954036\",\n        \"regexp\": {\n          \"pattern\": \"^((-?0*([0-9]|[1-8][0-9]|9[0-9]|1[0-6][0-9]|17[0-9])(\\\\.[0-9]{1,6})?)|-?180)$\",\n          \"modifiers\": \"\"\n        }\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"location\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"phone\",\n    \"type\": \"group\",\n    \"label\": \"Phone number\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"number\",\n        \"type\": \"text\",\n        \"label\": \"Phone number\",\n        \"description\": \"Phone number to call (please use the format +12 345 67890)\",\n        \"placeholder\": \"+12 345 67890\",\n        \"regexp\": {\n          \"pattern\": \"^\\\\+[0-9]{1,3}[\\\\ ]?[0-9]{1,4}[\\\\ ]?[0-9]{1,8}$\",\n          \"modifiers\": \"\"\n        }\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"phone\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"sms\",\n    \"type\": \"group\",\n    \"label\": \"SMS\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"number\",\n        \"type\": \"text\",\n        \"label\": \"Phone number\",\n        \"description\": \"Phone number to send to (please use the format +12 345 67890)\",\n        \"placeholder\": \"+12 345 67890\",\n        \"regexp\": {\n          \"pattern\": \"^\\\\+[0-9]{1,3}[\\\\ ]?[0-9]{1,4}[\\\\ ]?[0-9]{1,8}$\",\n          \"modifiers\": \"\"\n        }\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"text\",\n        \"label\": \"Message\",\n        \"description\": \"Message to send\",\n        \"placeholder\": \"Please fetch milk and bread!\",\n        \"maxLength\": 2000\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"sms\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"text\",\n    \"type\": \"group\",\n    \"label\": \"Text\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"text\",\n        \"type\": \"text\",\n        \"label\": \"Text\",\n        \"description\": \"Text to encode\",\n        \"placeholder\": \"Please fetch\\n* milk\\n* bread\",\n        \"widget\": \"textarea\",\n        \"maxLength\": 2000\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"text\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"url\",\n    \"type\": \"group\",\n    \"label\": \"URL\",\n    \"importance\": \"high\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"url\",\n        \"type\": \"text\",\n        \"label\": \"URL\",\n        \"description\": \"URL to link to (must start with https:// or http://)\",\n        \"placeholder\": \"https://fictional-h5p-fan-club.org\",\n        \"maxLength\": 2000,\n        \"regexp\": {\n          \"pattern\": \"https?://([0-9a-z.-]+).[a-z.]{2,}([0-9a-z.-_]*)*/?\",\n          \"modifiers\": \"i\"\n        }\n      }\n    ],\n    \"widget\": \"showWhen\",\n    \"showWhen\": {\n      \"rules\": [\n        {\n          \"field\": \"codeType\",\n          \"equals\": \"url\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"codeColor\",\n        \"type\": \"text\",\n        \"label\": \"Code color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#000000\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true\n        }\n      },\n      {\n        \"name\": \"backgroundColor\",\n        \"type\": \"text\",\n        \"label\": \"Background color\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"default\": \"#ffffff\",\n        \"widget\": \"colorSelector\",\n        \"spectrum\": {\n          \"showInput\": true,\n          \"showAlpha\": true,\n          \"preferredFormat\": \"rgb\"\n        }\n      },\n      {\n        \"name\": \"maxSize\",\n        \"type\": \"text\",\n        \"label\": \"Maximum size\",\n        \"description\": \"Maximum size for the code given in CSS notation (pixels by default if only a number is given)\",\n        \"importance\": \"medium\",\n        \"optional\": true,\n        \"regexp\": {\n          \"pattern\": \"^(([1-9]+.[0-9]+)|[0-9]+)(cm|mm|in|px|pt|pc|em|ex|ch|rem|vw|vh|vmin|vmax|%)?$\",\n          \"modifiers\": \"i\"\n        }\n      },\n      {\n        \"name\": \"alignment\",\n        \"type\": \"select\",\n        \"label\": \"Horizontal alignment\",\n        \"description\": \"Set horizontal alignment if you set a maximum size\",\n        \"options\": [\n          {\n            \"value\": \"left\",\n            \"label\": \"left\"\n          },\n          {\n            \"value\": \"center\",\n            \"label\": \"center\"\n          },\n          {\n            \"value\": \"right\",\n            \"label\": \"right\"\n          }\n        ],\n        \"default\": \"center\"\n      }\n    ]\n  },\n  {\n    \"name\": \"l10n\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"label\": \"User interface\",\n    \"importance\": \"low\",\n    \"fields\": [\n      {\n        \"name\": \"address\",\n        \"type\": \"text\",\n        \"label\": \"Address\",\n        \"importance\": \"low\",\n        \"defau